<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Holder\UserProfileLocaleAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserProfileLocaleAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserProfileLocaleAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getLocale returns null on a freshly created holder.
     */
    public function testLocaleNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileLocaleAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isLocaleAssigned());
        $this->assertNull($holder->getLocale());
    }
}
class ImplWithUserProfileLocaleAttributeHolderUnitTest
{
    use UserProfileLocaleAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedLocaleRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultLocale();
    }
}
